import { Pressable, StyleSheet, Text, View } from "react-native";
import type { StyleProp, TextStyle, ViewProps, ViewStyle } from "react-native";
import { metrics, useTokens } from "../lib/rn-tokens";

export interface PaginationProps extends ViewProps {
  page: number;
  pageCount: number;
  onPageChange: (page: number) => void;
  label?: string;
  /** Extend the inner, named parts of the pagination: button, current, step or text. The React Native counterpart of `classNames`. */
  styles?: {
    button?: StyleProp<ViewStyle>;
    current?: StyleProp<ViewStyle>;
    step?: StyleProp<ViewStyle>;
    text?: StyleProp<TextStyle>;
  };
}

export function Pagination({ page, pageCount, onPageChange, label = "Pagination", style, styles: parts, ...props }: PaginationProps) {
  const tokens = useTokens();
  const total = Math.max(0, Math.floor(pageCount));
  const current = total > 0 ? Math.min(Math.max(1, Math.floor(page)), total) : 0;
  // A window of five pages that follows the current one.
  const start = total > 0 ? Math.max(1, Math.min(total - 4, current - 2)) : 1;
  const visible = Array.from({ length: Math.min(total, 5) }, (_, index) => start + index);

  const cell = { width: metrics.controlHeight.sm, height: metrics.controlHeight.sm, borderRadius: metrics.radiusControl };

  return (
    <View {...props} accessibilityRole="toolbar" accessibilityLabel={label} style={[local.root, style]}>
      <Pressable
        accessibilityRole="button"
        accessibilityLabel="Previous page"
        disabled={current <= 1}
        onPress={() => onPageChange(current - 1)}
        style={({ pressed }) => [local.cell, cell, { opacity: current <= 1 ? 0.4 : 1, backgroundColor: pressed ? tokens.surfaceMuted : "transparent" }, parts?.step]}
      >
        <Text style={[{ color: tokens.textSecondary, fontSize: 18 }, parts?.text]}>‹</Text>
      </Pressable>
      {visible.map((number) => {
        const active = number === current;
        return (
          <Pressable
            key={number}
            accessibilityRole="button"
            accessibilityLabel={`Page ${number}`}
            accessibilityState={{ selected: active }}
            onPress={() => onPageChange(number)}
            style={({ pressed }) => [
              local.cell,
              cell,
              { borderWidth: 1, borderColor: active ? tokens.border : "transparent", backgroundColor: active ? tokens.surface : pressed ? tokens.surfaceMuted : "transparent" },
              parts?.button,
              active && parts?.current,
            ]}
          >
            <Text style={[{ color: active ? tokens.foreground : tokens.textSecondary, fontSize: metrics.text.xs, fontWeight: "500" }, parts?.text]}>{number}</Text>
          </Pressable>
        );
      })}
      <Pressable
        accessibilityRole="button"
        accessibilityLabel="Next page"
        disabled={current >= total}
        onPress={() => onPageChange(current + 1)}
        style={({ pressed }) => [local.cell, cell, { opacity: current >= total ? 0.4 : 1, backgroundColor: pressed ? tokens.surfaceMuted : "transparent" }, parts?.step]}
      >
        <Text style={[{ color: tokens.textSecondary, fontSize: 18 }, parts?.text]}>›</Text>
      </Pressable>
    </View>
  );
}

const local = StyleSheet.create({
  root: { flexDirection: "row", alignItems: "center", gap: metrics.space[1], alignSelf: "flex-start" },
  cell: { alignItems: "center", justifyContent: "center", borderWidth: 1, borderColor: "transparent" },
});

export default Pagination;

import { useColorScheme } from "react-native";

/** The Manicat UI design tokens as React Native values. Same names and meaning as registry/foundation.css. */
export interface ManicatTokens {
  background: string;
  surface: string;
  surfaceMuted: string;
  foreground: string;
  textSecondary: string;
  textMuted: string;
  border: string;
  borderStrong: string;
  accent: string;
  accentStrong: string;
  accentSubtle: string;
  success: string;
  warning: string;
  danger: string;
  controlOn: string;
  controlTrack: string;
  controlThumb: string;
  controlThumbOn: string;
}

export const lightTokens: ManicatTokens = {
  background: "#ffffff",
  surface: "#ffffff",
  surfaceMuted: "#f6f6f6",
  foreground: "#1b1b1b",
  textSecondary: "#6e6e6e",
  textMuted: "#8f8f8f",
  border: "#ebebeb",
  borderStrong: "#c9c9c9",
  accent: "#4a4a4a",
  accentStrong: "#303030",
  accentSubtle: "rgba(74, 74, 74, 0.1)",
  success: "#1f8a4c",
  warning: "#b8741a",
  danger: "#d03b3b",
  controlOn: "#2c2c2c",
  controlTrack: "#e2e2e2",
  controlThumb: "#ffffff",
  controlThumbOn: "#ffffff",
};

export const darkTokens: ManicatTokens = {
  background: "#2b2b2b",
  surface: "#303030",
  surfaceMuted: "#3c3c3c",
  foreground: "#f1f1f1",
  textSecondary: "#c4c4c4",
  textMuted: "#a0a0a0",
  border: "#454545",
  borderStrong: "#5c5c5c",
  accent: "#cfcfcf",
  accentStrong: "#e6e6e6",
  accentSubtle: "rgba(207, 207, 207, 0.13)",
  success: "#5fd48a",
  warning: "#f0b95c",
  danger: "#ff8a80",
  controlOn: "#ececec",
  controlTrack: "#515151",
  controlThumb: "#f4f4f4",
  controlThumbOn: "#2b2b2b",
};

/** Shape and rhythm shared by every component, in density-independent pixels. */
export const metrics = {
  radiusControl: 18,
  radiusPill: 9999,
  controlHeight: { sm: 36, md: 44, lg: 50 },
  space: { 1: 4, 2: 8, 3: 12, 4: 16, 5: 20 },
  text: { xs: 12, sm: 14, lg: 18 },
} as const;

/** The tokens for the device's current colour scheme. Wrap the app in your own provider if you manage the theme yourself. */
export function useTokens(): ManicatTokens {
  return useColorScheme() === "dark" ? darkTokens : lightTokens;
}
